const teams=D.teams;
const fmt=(x,d=1)=>Number(x).toFixed(d);
const done=D.matches;
function resultFor(m,t){let gf=m.home_team===t?+m.home_goals:+m.away_goals,ga=m.home_team===t?+m.away_goals:+m.home_goals;return gf>ga?'W':gf===ga?'D':'L'}
function sortedTable(){return [...D.table].sort((a,b)=>b.PTS-a.PTS||b.GD-a.GD||b.GF-a.GF||a.team.localeCompare(b.team))}
function last5(t){return done.filter(m=>m.home_team===t||m.away_team===t).sort((a,b)=>a.date.localeCompare(b.date)||a.kickoff_local.localeCompare(b.kickoff_local)).slice(-5)}
function resultSymbol(m,t){return resultFor(m,t)}
const rank=sortedTable();
let tbd=document.querySelector('#standings tbody');
if(!tbd.rows.length)rank.forEach((r,i)=>{let cl=i<4?'zone-champ':i>=17?'zone-releg':'';let label=i<4?'<span class="zone-label">UCL</span>':i<6?'<span class="zone-label europa">UEL</span>':i===6?'<span class="zone-label conference">UECL-Q</span>':i>=17?'<span class="zone-label releg">RELEG.</span>':'';let form=last5(r.team).map(m=>`<i class="${resultSymbol(m,r.team)}">${resultSymbol(m,r.team)}</i>`).join('');tbd.insertAdjacentHTML('beforeend',`<tr class="${cl}"><td>${i+1}</td><td class="team-name">${r.team}${label}</td><td>${r.P}</td><td>${r.W}</td><td>${r.D}</td><td>${r.L}</td><td>${r.GF}</td><td>${r.GA}</td><td>${r.GD>0?'+':''}${r.GD}</td><td><b>${r.PTS}</b></td><td><div class="form">${form||'—'}</div></td></tr>`)});
const gamesPerTeam=done.length/teams.length*2;
let top=rank[0];let goals=done.reduce((s,m)=>s+ +m.home_goals + +m.away_goals,0);
document.getElementById('kpis').innerHTML=`<div class="card kpi"><span class="label">Líder · ${top.team}</span><strong>${top.PTS} pts</strong><small>${top.W}V · ${top.D}E · ${top.L}D</small></div><div class="card kpi"><span class="label">Partidas concluídas</span><strong>${done.length}</strong><small>de 380 jogos no calendário · ${D.completeRounds.length} jornadas completas</small></div><div class="card kpi"><span class="label">Gols confirmados</span><strong>${goals}</strong><small>${fmt(goals/done.length,2)} por partida</small></div><div class="card kpi"><span class="label">Clubes</span><strong>${teams.length}</strong><small>20 na temporada 2026/27</small></div>`;
const r7=D.fixtures.filter(g=>g.round===D.lastCompleteRound).sort((a,b)=>a.date.localeCompare(b.date));
document.getElementById('round7').innerHTML=r7.map(g=>`<div class="match"><span class="team-name">${g.home}</span><span class="score">${g.status==='finished'?`${g.home_goals??''}–${g.away_goals??''}`:(g.status==='live'?'AO VIVO':'—')} <span class="badge ${g.status==='live'?'live':''}">${g.status==='finished'?'FINALIZADO':g.status==='live'?'EM ANDAMENTO':'AGENDADO'}</span></span><span class="team-name right">${g.away}</span></div>`).join('');
const roundSelect=document.getElementById('roundSelect');
const nextRound=D.fixtures.filter(g=>g.status!=='finished').map(g=>g.round).sort((a,b)=>a-b)[0]||1;
roundSelect.innerHTML=Array.from({length:38},(_,i)=>`<option value="${i+1}">Jornada ${i+1}</option>`).join('');
roundSelect.value=String(nextRound);
const fmtShortDate=s=>s?s.slice(8,10)+'/'+s.slice(5,7)+'/'+s.slice(0,4):'';
function renderFixtures(){const md=+roundSelect.value;const marker=D.roundDates[String(md)]||'';const games=D.fixtures.filter(g=>g.round===md).sort((a,b)=>a.home.localeCompare(b.home));document.getElementById('roundMeta').textContent=marker?`Data-guia oficial da jornada: ${fmtShortDate(marker)}. Esse marcador não é a data/horário individual de cada partida; para MD11–38, o kickoff segue a confirmar.`:'Marcador oficial da jornada indisponível.';document.getElementById('fixturesList').innerHTML=games.map(g=>{const exact=g.date?`Partida: ${fmtShortDate(g.date)}${g.time?' · '+g.time:''}`:'Data e horário individuais a confirmar';const score=g.status==='finished'?`${g.home_goals}–${g.away_goals}`:g.status==='live'?'AO VIVO':'—';const badge=g.status==='finished'?'FINALIZADO':g.status==='live'?'EM ANDAMENTO':g.date?'AGENDADO':'DATA/HORA A CONFIRMAR';return `<div class="match"><span class="team-name">${g.home}</span><span class="score">${score}<br><small class="small-note">${exact}</small><br><span class="badge ${g.status==='live'?'live':''}">${badge}</span></span><span class="team-name right">${g.away}</span></div>`}).join('')||'<div class="empty">Nenhum jogo cadastrado para esta jornada.</div>'}
roundSelect.addEventListener('change',renderFixtures);renderFixtures();
function populate(sel){sel.innerHTML=teams.map(t=>`<option value="${t}">${t}</option>`).join('')};populate(document.getElementById('teamSelect'));populate(document.getElementById('homeSelect'));populate(document.getElementById('awaySelect'));
document.getElementById('homeSelect').value='Inter';document.getElementById('awaySelect').value='Roma';
function teamDetail(t){let z=D.table.find(x=>x.team===t),arr=done.filter(m=>m.home_team===t||m.away_team===t).sort((a,b)=>b.date.localeCompare(a.date)||b.kickoff_local.localeCompare(a.kickoff_local)).slice(0,5);let ups=D.fixtures.filter(g=>(g.home===t||g.away===t)&&g.status!=='finished').sort((a,b)=>a.round-b.round).slice(0,5);let upcoming=ups.map(g=>`<div class="match"><span class="team-name">${g.home===t?'vs':'@'} ${g.home===t?g.away:g.home}</span><span class="score">MD ${g.round}${g.roundDateLabel?`<br><small class="small-note">round date ${g.roundDateLabel}</small>`:''}</span><span class="right"><span class="badge ${g.status==='live'?'live':''}">${g.status==='live'?'AO VIVO':'PRÓXIMO'}</span></span></div>`).join('')||'<div class="empty">No upcoming fixtures found in the official 38-round calendar.</div>';let playedHome=done.filter(m=>m.home_team===t),playedAway=done.filter(m=>m.away_team===t);let form=arr.map(m=>{let res=resultFor(m,t),score=`${m.home_goals}–${m.away_goals}`;return `<div class="match"><span class="team-name">${m.home_team===t?'vs':'@'} ${m.home_team===t?m.away_team:m.home_team}</span><span class="score">${score}</span><span class="right"><i class="${res}" style="display:inline-grid;place-items:center;width:22px;height:22px;border-radius:50%;font-style:normal;font-weight:800">${res}</i> <small class="muted">${m.date}</small></span></div>`}).join('')||'<div class="empty">No completed match.</div>';document.getElementById('teamDetail').innerHTML=`<div class="metrics"><div class="metric"><small>Geral · ${z.P} jogos</small><strong>${z.PTS} pts</strong></div><div class="metric"><small>Casa · ${z.homeP} jogos</small><strong>${z.homeW}V ${z.homeD}E ${z.homeL}D</strong></div><div class="metric"><small>Fora · ${z.awayP} jogos</small><strong>${z.awayW}V ${z.awayD}E ${z.awayL}D</strong></div></div><div class="detail-grid" style="margin-top:16px"><div class="card"><h3>Últimos 5 encerrados</h3>${form}</div><div class="card"><h3>Próximos jogos disponíveis</h3>${upcoming}<p class="small-note">A data do cabeçalho é apenas o marcador oficial da giornata, não o kickoff individual. Datas e horários de MD11–38 aguardam confirmação.</p></div></div><div class="split" style="margin-top:14px"><div class="card"><h3>Produção e defesa</h3><div class="statline"><span>Gols a favor / contra</span><b>${z.GF} / ${z.GA}</b></div><div class="statline"><span>Saldo</span><b>${z.GD>0?'+':''}${z.GD}</b></div><div class="statline"><span>Casa · GF/GC</span><b>${z.homeGF}/${z.homeGA}</b></div><div class="statline"><span>Fora · GF/GC</span><b>${z.awayGF}/${z.awayGA}</b></div></div><div class="card"><h3>Desempenho por mando</h3><div class="statline"><span>Casa · pontos/jogo</span><b>${z.homeP?fmt((3*z.homeW+z.homeD)/z.homeP,2):'—'}</b></div><div class="statline"><span>Fora · pontos/jogo</span><b>${z.awayP?fmt((3*z.awayW+z.awayD)/z.awayP,2):'—'}</b></div><div class="statline"><span>Jogos sem sofrer gol</span><b>${done.filter(m=>(m.home_team===t&&+m.away_goals===0)||(m.away_team===t&&+m.home_goals===0)).length}/${z.P}</b></div></div></div>`}
teamDetail('Inter');document.getElementById('teamSelect').addEventListener('change',e=>teamDetail(e.target.value));
function poisson(l,k){let p=Math.exp(-l);for(let i=1;i<=k;i++)p*=l/i;return p}function analyze(home,away){if(home===away){document.getElementById('matchupResult').innerHTML='<div class="empty">Escolha equipes diferentes.</div>';return}let h=done.filter(m=>m.home_team===home),a=done.filter(m=>m.away_team===away);let hg=h.length,aa=a.length;if(hg<2||aa<2){document.getElementById('matchupResult').innerHTML=`<div class="empty">Amostra insuficiente para projetar com este mando. ${home} em casa: ${hg} jogo(s); ${away} fora: ${aa} jogo(s). Mínimo: 2 por lado.</div>`;return}let leagueHome=done.reduce((s,m)=>s+(+m.home_goals),0)/done.length,leagueAway=done.reduce((s,m)=>s+(+m.away_goals),0)/done.length;let hGF=h.reduce((s,m)=>s+(+m.home_goals),0)/hg,hGA=h.reduce((s,m)=>s+(+m.away_goals),0)/hg,aGF=a.reduce((s,m)=>s+(+m.away_goals),0)/aa,aGA=a.reduce((s,m)=>s+(+m.home_goals),0)/aa;let exH=(hGF+aGA+leagueHome)/3,exA=(aGF+hGA+leagueAway)/3;let p1=0,px=0,p2=0,btts=0,o25=0,peak=0,modal='';for(let i=0;i<=8;i++)for(let j=0;j<=8;j++){let p=poisson(exH,i)*poisson(exA,j);if(i>j)p1+=p;else if(i===j)px+=p;else p2+=p;if(i>0&&j>0)btts+=p;if(i+j>=3)o25+=p;if(p>peak){peak=p;modal=`${i}–${j}`}}let h2=done.filter(m=>(m.home_team===home&&m.away_team===away)||(m.home_team===away&&m.away_team===home));document.getElementById('matchupResult').innerHTML=`<div class="card project"><div class="proj-heading">${home} (casa) × ${away} (fora)</div><div class="muted">Projeção simples Poisson · ${hg} jogos caseiros de ${home}, ${aa} jogos fora de ${away}</div><div class="metrics" style="margin:14px 0"><div class="metric"><small>Gols esperados</small><strong>${fmt(exH,2)} – ${fmt(exA,2)}</strong></div><div class="metric"><small>Placar modal</small><strong>${modal}</strong></div><div class="metric"><small>H2H na temporada</small><strong>${h2.length} jogo(s)</strong></div></div><div class="probrow"><b>1 ${fmt(p1*100,1)}%</b><b>X ${fmt(px*100,1)}%</b><b>2 ${fmt(p2*100,1)}%</b></div><div class="probbar"><span style="width:${p1*100}%"></span><span style="width:${px*100}%"></span><span style="width:${p2*100}%"></span></div><div class="probrow"><span>BTTS: <b>${fmt(btts*100,1)}%</b></span><span>Mais de 2,5: <b>${fmt(o25*100,1)}%</b></span></div><p class="small-note" style="color:#d6e5e6;margin-top:12px">Estimativa de gols: ataque caseiro/defesa visitante e ataque visitante/defesa caseira, com estabilização pela média da liga. Resultados independentes; não é uma previsão validada.</p></div>`}
function h2h(){let h=document.getElementById('homeSelect').value,a=document.getElementById('awaySelect').value;let games=done.filter(m=>(m.home_team===h&&m.away_team===a)||(m.home_team===a&&m.away_team===h));document.getElementById('h2h').innerHTML=games.length?games.map(m=>`<div class="match"><span class="team-name">${m.home_team}</span><span class="score">${m.home_goals}–${m.away_goals}<br><small>${m.date}</small></span><span class="team-name right">${m.away_team}</span></div>`).join(''):`<div class="empty">Nenhum confronto direto encerrado entre ${h} e ${a} nesta temporada.</div>`}
function renderMatch(){analyze(document.getElementById('homeSelect').value,document.getElementById('awaySelect').value);h2h()}document.getElementById('homeSelect').addEventListener('change',renderMatch);document.getElementById('awaySelect').addEventListener('change',renderMatch);renderMatch();
function renderTop(){let split=document.getElementById('splitSelect').value;let m=done;let rows=teams.map(t=>{let g=split==='all'?m:m.filter(x=>split==='home'?x.home_team===t:x.away_team===t);let P=g.length,W=0,D=0,L=0,GF=0,GA=0,B=0,O=0;for(let x of g){let gf=split==='away'?+x.away_goals:+x.home_goals,ga=split==='away'?+x.home_goals:+x.away_goals;GF+=gf;GA+=ga;if(gf>ga)W++;else if(gf<ga)L++;else D++;if(+x.home_goals>0&&+x.away_goals>0)B++;if(+x.home_goals + +x.away_goals>=3)O++}return {team:t,P,W,D,L,GF,GA,PTS:3*W+D,B,O,GD:GF-GA}});let cards=[['Pontos','PTS','count'],['Gols pró','GF','count'],['Melhor defesa · menos GC','GA','asc'],['Vitórias','W','count'],['Empates','D','count'],['Derrotas','L','count'],['Ambas marcam','B','rate'],['Over 2.5 gols','O','rate']];document.getElementById('top5Grid').innerHTML=cards.map(([title,key,mode])=>{let q=[...rows].sort((a,b)=>mode==='asc'?a.GA-b.GA:(mode==='rate'?(b[key]/(b.P||1)-a[key]/(a.P||1)):b[key]-a[key])||b.P-a.P).slice(0,5);return `<div class="card"><h3>${title} <span class="small-note">· ${split==='all'?'geral':split==='home'?'casa':'fora'}</span></h3>${q.map((x,i)=>`<div class="top5item"><span class="rank">${i+1}</span><span><b>${x.team}</b><br><small class="small-note">${mode==='rate'?`${x[key]}/${x.P} jogos · ${x.P?fmt(100*x[key]/x.P,1):'0.0'}%`:`${key==='PTS'?x.PTS:x[key]}${key==='GA'?' gols sofridos':''} · ${x.P} jogos`}</small></span><b>${mode==='rate'?fmt(100*x[key]/x.P,1)+'%':key==='PTS'?x.PTS:key==='GA'?x.GA:x[key]}</b></div>`).join('')}</div>`}).join('')}
document.getElementById('splitSelect').addEventListener('change',renderTop);renderTop();
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById(b.dataset.tab).classList.add('active')}));
window.__DASH_TEST={teamCount:teams.length,finishedCount:done.length,fixtureCount:D.fixtures.length,rankCount:rank.length,canSwitch:document.querySelectorAll('.tab').length,top5Cards:8,matchupReady:typeof analyze==='function',calendarReady:typeof renderFixtures==='function'};
document.querySelectorAll('[data-js-enable]').forEach(e=>e.hidden=false);
document.documentElement.classList.add('js-ready');if(jsStatus){jsStatus.textContent='Filtros dinâmicos carregados.';jsStatus.hidden=true;}
